new_groups as (
  insert into public.groups (name)
  select distinct r.group_name from raw r
   where r.group_name is not null
     and not exists (select 1 from public.groups g where upper(g.name) = upper(r.group_name))
  returning id, name
)
insert into public.members (
  full_name, gender, phone, phone_alt, email, date_of_birth, marital_status,
  postal_address, location_landmark, communication_prefs, ministries,
  member_type, joined_on, baptism_date, group_id, talents,
  emergency_name, emergency_phone, age_group, is_active)
select r.full_name, r.gender, r.phone, r.phone_alt, r.email, r.date_of_birth, r.marital_status,
       r.postal_address, r.location_landmark, r.communication_prefs, r.ministries,
       r.member_type, coalesce(r.joined_on, current_date), r.baptism_date,
       coalesce(g.id, ng.id), r.talents, r.emergency_name, r.emergency_phone,
       case
         when r.date_of_birth is null then 'Adults'
         when extract(year from age(r.date_of_birth)) < 13 then 'Children'
         when extract(year from age(r.date_of_birth)) < 25 then 'Youth'
         when extract(year from age(r.date_of_birth)) < 36 then 'Young Adults'
         when extract(year from age(r.date_of_birth)) < 60 then 'Adults'
         else 'Seniors'
       end,
       true
  from raw r
  left join public.groups g on upper(g.name) = upper(r.group_name)
  left join new_groups ng on upper(ng.name) = upper(r.group_name);
